SELECT r.* FROM review r

    r.product_id = #{productId}

        AND r.rating = #{rating}


        AND EXISTS (SELECT 1 FROM review_image ri WHERE ri.review_id = r.id)


ORDER BY r.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM review
WHERE product_id = #{productId}

    AND rating = #{rating}


    AND id IN (SELECT DISTINCT review_id FROM review_image)

SELECT r.id, r.order_item_id as orderItemId, r.product_id as productId, r.user_id as userId, r.merchant_id as merchantId, r.content, r.rating, r.like_count as likeCount, r.has_append as hasAppend, r.is_anonymous as isAnonymous, r.is_top as isTop, r.create_time as createTime, p.name as productName, p.cover_img as productImage, rr.id as replyId, rr.content as replyContent, rr.create_time as replyTime, CASE WHEN rr.id IS NOT NULL THEN 1 ELSE 0 END as hasReply FROM review r LEFT JOIN product p ON r.product_id = p.id LEFT JOIN review_reply rr ON r.id = rr.review_id WHERE r.merchant_id = #{merchantId}
AND r.rating IN (4, 5)
AND r.rating = 3
AND r.rating IN (1, 2)
AND rr.id IS NOT NULL
AND rr.id IS NULL
AND r.create_time >= #{startTime}
AND r.create_time <= #{endTime}
ORDER BY r.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT r.id) FROM review r LEFT JOIN review_reply rr ON r.id = rr.review_id WHERE r.merchant_id = #{merchantId}
AND r.rating IN (4, 5)
AND r.rating = 3
AND r.rating IN (1, 2)
AND rr.id IS NOT NULL
AND rr.id IS NULL
AND r.create_time >= #{startTime}
AND r.create_time <= #{endTime}

mapper.update:
UPDATE review 
SET merchant_reply = #{merchantReply}, 
    reply_time = #{replyTime}
WHERE id = #{id}
